input.command:
node -e '
const fs=require("fs");
const t=fs.readFileSync(".github/workflows/deploy.yml","utf8");
const checks=[
  [/id-token:\s*write/, "id-token write"],
  [/workload_identity_provider:/, "wif provider"],
  [/github-actions\/providers\/github/, "provider resource"],
  [/github-actions-deploy@/, "deploy SA"],
  [/credentials_json/, "must NOT have credentials_json"],
  [/GCP_SA_KEY/, "must NOT require GCP_SA_KEY"],
];
for (const [re,label] of checks) {
  const hit=re.test(t);
  const want=!label.startsWith("must NOT");
  if (hit!==want) { console.error("FAIL", label, "hit="+hit); process.exit(1); }
  console.log("ok:", label);
}
console.log("lines", t.split(/\n/).length);
'
# Confirm WIF provider still exists
gcloud iam workload-identity-pools providers describe github \
  --project=project-ec366840-6857-446e-852 \
  --location=global \
  --workload-identity-pool=github-actions \
  --format='yaml(name,attributeCondition,issuerUri)' 2>&1

git status --short
git diff --stat
